<?php foreach(['bank-zuordnung'=>'Bankumsatz zuordnen','bank-abrufe'=>'Bankübernahme prüfen','eigene-geldtransfers'=>'Abhebung oder Einzahlung zuordnen','finanzablauf'=>'Rechnung prüfen und bezahlen']as$id=>$title):?><li><a href="#<?=e($id)?>"><?=e($financeHelpText($title))?></a></li><?php endforeach?>
</ul><details><summary><?=e($financeHelpText('Alle Themen und Sonderfälle'))?></summary><ul class="finance-help-all"><?php foreach(\Kulturhus\Native\Language\FinanceHelpMessages::TOPICS as$id=>$title):?><li><a href="#<?=e($id)?>"><?=e($financeHelpText($title))?></a></li><?php endforeach?></ul></details></nav>

<section class="card" data-finance-help-topic id="finanzablauf"><h2><?= $financeHelpHtml('Die drei Schritte') ?></h2><ol class="finance-simple-steps">
<li><strong><?= e($financeHelpText('Eingang')) ?></strong><p><a class="btn btn-outline theme-secondary button secondary" href="?view=finance&amp;tab=inbox"><?= $financeHelpHtml('Rechnungseingang öffnen') ?></a></p><p><?= $financeHelpHtml('Rechnung hochladen oder einen vorhandenen Eingang öffnen. Beim Speichern wählen Sie, wer bezahlt hat. Hat ein Mitglied privat bezahlt, wählen Sie das Mitglied direkt dort aus.') ?></p></li>
<li><strong><?= e($financeHelpText('Prüfen')) ?></strong><p><?= $financeHelpHtml('Originalrechnung, Empfänger, Rechnungsnummer, Datum und Gesamtbetrag vergleichen. Die vorgeschlagene Zuordnung prüfen. Nur bei mehreren Artikeln oder Inventar die Positionen öffnen.') ?></p><p><?= $financeHelpHtml('Danach <strong>Rechnung prüfen und freigeben</strong>.') ?></p></li>
<li><strong><?= e($financeHelpText('Bezahlen')) ?></strong><p><?= $financeHelpHtml('Den Zahlungsweg auswählen. Einen vorhandenen Kontoumsatz zuordnen oder eine Überweisung über das Vereinskonto starten. Eine private Vorleistung wird dem ausgewählten Mitglied erstattet.') ?></p></li>
</ol><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>
<section class="card" data-finance-help-topic id="beleg-erfassung"><h2><?= $financeHelpHtml('Beleg mit Originaldatei erfassen und fortsetzen') ?></h2><p><?= $financeHelpHtml('Eine Einnahme, Ausgabe, einen Beitrag oder eine Geldspende im vorhandenen Belegbereich erfassen. <strong>Angaben und Belegtyp anzeigen</strong> zeigt nur die Ansicht; es speichert weder Beleg noch Zahlung. Ohne JavaScript lassen sich Positionen ausdrücklich hinzufügen und entfernen.') ?></p><p><?= $financeHelpHtml('Die ausgewählte Originaldatei bleibt bei Fehlern und Positionsänderungen privat erhalten. Nur bewusstes Entfernen löscht diese Auswahl. Bei einer privaten Vorleistung Mitglied und Rechnungsempfänger auswählen. Fehler behalten die ursprünglichen Angaben. Erst <strong>Beleg speichern</strong> legt den offenen Beleg mit seinem Original an.') ?></p><p><?= $financeHelpHtml('Nach einer unterbrochenen Antwort zuerst <strong>Gespeicherten Belegstand lesen</strong> verwenden. Ein bereits gespeicherter Ausgang wird mit derselben ursprünglichen Kennung gelesen; Datei und Erstattung werden nicht erneut angelegt. Danach die tatsächlich vorhandene Zahlung ausdrücklich zuordnen.') ?></p><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>


<section class="card" data-finance-help-topic id="belegschritte"><h2><?= $financeHelpHtml('Schritte im geöffneten Beleg') ?></h2><p><?= $financeHelpHtml('<strong>Beleg</strong> öffnet die ursprünglichen Angaben. Bei Einnahmen, Beiträgen und Geldspenden folgt <strong>Zahlung</strong> zur passenden Zuordnung. Ausgaben führen zusätzlich über <strong>Prüfen</strong> zur Freigabe. Bei bezahlten, gegengebuchten oder verworfenen Belegen öffnet <strong>Verlauf</strong> den gespeicherten Zahlungsstand. Mit Leserecht bleiben die Schritte lesend. Beleg, Konto und bisherige Bankfilter bleiben erhalten.') ?></p><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>

<section class="card" data-finance-help-topic id="zahlungsrueckfuehrung"><h2><?= $financeHelpHtml('Zurückgekommene Zahlung: Forderungen offen halten') ?></h2><p><?= $financeHelpHtml('Öffne den ursprünglichen Kontoumsatz und „Zahlung zurückgekommen – Forderungen bleiben offen“. Prüfe alle ursprünglichen Belege und wähle die bereits erfasste vollständige Rückzahlung auf demselben Konto. Nach aktueller Prüfung gesondert bestätigen. Die Forderungen werden wieder offen; Originalbelege und Kontostand bleiben erhalten.') ?></p><p><?= $financeHelpHtml('Eine ausgestellte Originalrechnung bleibt gültig. Zugehörige Gutschriften, Stornos, bescheinigte Spenden, private Vorleistungen und laufende Bankaufträge zuerst klären. Für eine laufende Lastschrift den Rücklastschriftweg verwenden. Für Teilrückzahlungen und mehrere ursprüngliche Zahlungsquellen die vorhandene Rückzahlung öffnen und „Teilbetrag oder mehrere ursprüngliche Zahlungen zurückgekommen“ verwenden.') ?></p><p><?= $financeHelpHtml('Ist eine frühere eingereichte Überweisung vollständig zurückgekommen, beide tatsächlichen Banknachweise zuordnen und den betroffenen Bankauftrag anschließend unter „Zurückgekommenen Bankauftrag ausdrücklich zuordnen“ mit bestätigter Zahlungsberechtigung neu prüfen und gesondert bestätigen. Erst danach einen neuen beleggebundenen Auftrag vorbereiten. Der alte Auftrag und seine Bankdatei bleiben erhalten; dieselbe Datei nicht erneut einreichen.') ?></p><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>

<section class="card" data-finance-help-topic id="teilrueckzahlung"><h2><?= $financeHelpHtml('Teilrückzahlung auf ursprüngliche Zahlungen verteilen') ?></h2><p><?= $financeHelpHtml('Öffne die tatsächlich vorhandene Rückzahlung und <strong>Teilbetrag oder mehrere ursprüngliche Zahlungen zurückgekommen</strong>. Wähle eine bis vierzig ursprüngliche Zahlungszuordnungen und die tatsächlich zurückgekommenen Teilbeträge. Auch verschiedene eigene Konten und Kassen sind möglich. Nach <strong>Alle Teilbeträge und Originale aktuell prüfen</strong> die Beträge und Originalbelege vergleichen und gesondert bestätigen.') ?></p><p><?= $financeHelpHtml('Die ursprünglichen Forderungen bleiben gültig. Nur die zurückgekommenen Beträge werden wieder offen; ursprüngliche Zahlungen und Kontostand bleiben erhalten. Eine falsche Verteilung mit Grund neu prüfen und ausdrücklich zurücknehmen. Bereits erneut bezahlte Beträge und laufende Folgeaufträge zuerst klären. Für laufende Lastschriften, bescheinigte Spenden, private Vorleistungen und Rechnungskorrekturen den zugehörigen Fachweg verwenden.') ?></p><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>
<section class="card" data-finance-help-topic id="bankausfuehrung"><h2><?= $financeHelpHtml('Alten Bankauftrag nach Teilrückzahlung klären') ?></h2><p><?= $financeHelpHtml('Unter <strong>Ausführung eines ursprünglichen Bankauftrags zuordnen</strong> den tatsächlichen alten eingereichten Auftrag und alle seine ursprünglichen Zahlungszuordnungen bewusst auswählen. Ihre Summe muss den alten Auftragsbetrag ergeben. Originalzahlung und sämtliche Bankrückzahlungen benötigen vollständige tatsächliche Bankbezüge, eine Barerstattung ihren gezählten Kassenabschluss. Mit bestätigter Zahlungsberechtigung Grund und konkreten Nachweis eingeben, aktuell prüfen und gesondert bestätigen.') ?></p><p><?= $financeHelpHtml('Danach die Originalrechnung erneut prüfen und freigeben; erst anschließend einen eigenen neuen Auftrag über den wirklich offenen Rest vorbereiten. Der alte Auftrag bleibt erhalten. <strong>Falschen Ausführungsnachweis zurücknehmen</strong> benötigt einen eigenen Grund und neue Bestätigung. Laufende Folgeaufträge zuerst klären.') ?></p><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>

<section class="card" data-finance-help-topic id="native-ruecklastschrift"><h2><?= $financeHelpHtml('Rücklastschrift und ursprüngliche Einzugszahlungen gemeinsam zuordnen') ?></h2><p><?= $financeHelpHtml('Öffne den ursprünglichen Lastschriftauftrag, wähle den Einzug und den bereits erfassten tatsächlichen Rückumsatz. Unter <strong>Ursprüngliche Einzugszahlungen zuordnen</strong> eine bis vierzig tatsächliche Zuordnungen wählen. Ihre Summe muss genau dem Einzugsbetrag entsprechen. Eine 100-Euro-Zahlung kann beispielsweise in zwei Schritten mit 60 und 40 Euro zugeordnet worden sein.') ?></p><p><?= $financeHelpHtml('Nach der ganzen aktuellen Prüfung <strong>Danach bezahlt / Danach offen</strong> vergleichen und gesondert bestätigen. Lastschriftstatus und Finanzzuordnung werden gemeinsam gespeichert. Die ursprüngliche Rechnung, Zahlungen und Bankdatei bleiben erhalten. Im Belegverlauf stehen ursprünglicher, zurückgekommener und noch bezahlter Anteil. Eine dokumentierte Rücklastschrift lässt sich nicht durch isoliertes Lösen ihrer Finanzzuordnung korrigieren. Im ursprünglichen Lastschriftauftrag können frühere Rückläufe bewusst finanziell nachzugeordnet, vorhandene Rückzahlungsnachweise verknüpft oder Rücklastschrift und Finanzzuordnung gemeinsam zurückgenommen werden. Grund und tatsächlichen Banknachweis vollständig angeben, den danach bezahlten und offenen Betrag prüfen und gesondert bestätigen. Die gemeinsame Rücknahme sendet keinen neuen Bankauftrag und erhält sämtliche Originale.') ?></p><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>

<section class="card" data-finance-help-topic id="gemeinsame-gegenbuchung"><h2><?= $financeHelpHtml('Gemeinsam bezahlte Belege vollständig korrigieren') ?></h2><p><?= $financeHelpHtml('Öffne den ursprünglichen Kontoumsatz und „Gemeinsam bezahlte Belege vollständig gegenbuchen“. Prüfe alle vollständig bezahlten Originalbelege und wähle die bereits erfasste gleich hohe Gegenbewegung. Nach aktueller Prüfung gesondert bestätigen. Es wird kein neuer Kontoumsatz erfasst.') ?></p><p><?= $financeHelpHtml('Alle aufgeführten Belege werden vollständig korrigiert. Für weiterhin gültige Forderungen „Zahlung zurückgekommen – Forderungen bleiben offen“ verwenden. Für Teilrückzahlungen den Teilrückzahlungsweg an der vorhandenen Rückzahlung verwenden. Ausgestellte Rechnungen über ihren Storno- oder Gutschriftweg bearbeiten. Der gespeicherte gemeinsame Korrekturbeleg bleibt mit Finanz-Leserecht und aktuellen Dateirechten abrufbar.') ?></p><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>

<section class="card" data-finance-help-topic id="banknachweis-gebuehr"><h2><?= $financeHelpHtml('Tatsächlich einbehaltene Bankgebühr mit Original zuordnen') ?></h2><p><?= $financeHelpHtml('100 Euro erfasste Zahlung und ein Euro belegte Gebühr ergeben 99 Euro Bankeingang. Wähle <strong>Bankabrufe prüfen → Vorhandene Zahlungen mit belegtem Gebührenabzug zuordnen</strong>. Ergänze die ursprüngliche Zahlung und wähle einen vollständig unbezahlten eigenen Ausgabebeleg über genau die tatsächliche Gebühr. Der hochgeladene Originalbeleg muss geprüft und freigegeben sein. Ein fehlender Gebührenbeleg kann im neuen Fenster im bestehenden Belegablauf erfasst werden; das Bankformular bleibt geöffnet.') ?></p><p><?= $financeHelpHtml('Prüfe vorhandene Zahlungen, Gebühr und Banknetto bewusst und bestätige anschließend gesondert. Genau die tatsächliche Gebühr wird als Ausgabe erfasst und zugeordnet. Die ursprüngliche Zahlung bleibt erhalten; der Nettobetrag wird nicht nochmals gebucht. Bereits erfasste Gebühren als vorhandene Bewegung verbinden. Eine Betragsdifferenz allein bestätigt keine Gebühr. Eine Spende über 150 Euro bleibt auch bei einem Euro Bankgebühr eine Spende über 150 Euro.') ?></p><p><?= $financeHelpHtml('Eine frühere zusätzliche Nettoübernahme über <strong>Bisherige Entscheidung korrigieren → Doppelte Übernahme → Vorhandene Zahlungen mit belegtem Gebührenabzug</strong> auf die wirklichen Zahlungen zurückführen. Es entstehen der belegte Abzug und genau eine Gegenbuchung des Duplikats. Bei geändertem Original oder verlorener Antwort zunächst den gespeicherten Stand prüfen; die ursprünglichen Angaben und Nachweise bleiben erhalten.') ?></p><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>
<section class="card" data-finance-help-topic id="banknachweis-teilbetraege"><h2><?= $financeHelpHtml('Eine vorhandene Zahlung durch mehrere Bankzeilen belegen') ?></h2><p><?= $financeHelpHtml('Eine erfasste Zahlung über 150 Euro kann durch 100 Euro und später 50 Euro bei der Bank bestätigt werden. Öffne <strong>Bankabrufe prüfen → Bankteilbeträge vorhandener Bewegungen belegen</strong>. Ergänze die ursprüngliche Bewegung und gib den Teilbetrag dieser Bankzeile positiv ein. Eingang oder Ausgang stammt aus der ursprünglichen Bewegung. Prüfe die vollständige vorzeichenrichtige Summe bewusst und bestätige sie anschließend gesondert. Nach 100 Euro stehen 50 Euro <strong>Noch ohne Banknachweis</strong>; die Rechnungszahlung und der Kontostand bleiben erhalten.') ?></p><p><?= $financeHelpHtml('Für die zweite Bankzeile den verbleibenden Teil erneut prüfen. Andere Fenster behalten ihre ursprünglichen Angaben und brauchen nach einer Änderung eine neue Prüfung. Dieselbe tatsächliche Teilzahlung über die angebotene frühere Zusammenfassung wiederverwenden; mehrere Referenzen zählen denselben Teil einmal. Ein falscher Bezug lässt sich lösen, ohne seine Originalbytes zu ändern. Eine frühere zusätzliche Bankübernahme über <strong>Bisherige Entscheidung korrigieren → Doppelte Übernahme → Bankteilbeträge vorhandener Bewegungen</strong> auf den tatsächlichen Teil zurückführen. Genau eine Gegenbuchung gleicht das Duplikat aus. Eine verlorene Antwort zuerst anhand des gespeicherten Verlaufs prüfen.') ?></p><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>
<section class="card" data-finance-help-topic id="banknachweis-sammel"><h2><?= $financeHelpHtml('Mehrere vorhandene Zahlungen und Gebühren gemeinsam belegen') ?></h2><p><?= $financeHelpHtml('Fasst die Bank zwei vorhandene Teilzahlungen über je 50,00 EUR als 100,00 EUR zusammen, wähle in <strong>Bankabrufe prüfen</strong> den Weg <strong>Mit mehreren vorhandenen Teilbewegungen verbinden</strong>. Auch 100,00 EUR Zahlung und −1,00 EUR Gebühr ergeben gemeinsam 99,00 EUR. Die vollständigen tatsächlichen Bewegungen auf demselben Bankkonto auswählen, die vorzeichenrichtige Summe bewusst prüfen und anschließend gesondert bestätigen. Die Belege und der Kontostand bleiben erhalten.') ?></p><p><?= $financeHelpHtml('Weitere Suchseiten erhalten die Auswahl. Eine zweite Bankreferenz kann nach Prüfung dieselbe vollständige Zusammenfassung belegen. Ein falscher Bankbezug lässt sich begründet lösen; sein Original bleibt im Verlauf. Frühere Doppelübernahmen über <strong>Bisherige Entscheidung korrigieren → Mehrere vorhandene Teilbewegungen</strong> mit genau einer Gegenbuchung ausgleichen. Bei Änderungen oder unterbrochener Antwort den gespeicherten Ausgang lesen; Auswahl und Grund nicht durch eine zusätzliche Zahlung ersetzen.') ?></p><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>
<section class="card" data-finance-help-topic id="banknachweis-vorhanden"><h2><?= $financeHelpHtml('Späteren Banknachweis mit bereits vorhandenem Geld verbinden') ?></h2><p><?= $financeHelpHtml('Unter <strong>Bankabrufe prüfen</strong> bleiben bereits bezahlte Belege, Teilzahlungen sowie Abhebungen und Einzahlungen auch bei abweichendem Bankdatum als vorhandene Zahlungen erreichbar. Vergleiche Konto, Betrag, Richtung und tatsächlichen Nachweis. <strong>Mit einer vorhandenen Zahlung verbinden</strong> ergänzt nur den Bankbezug; Kontostand, Belegzahlung und Bank-Kasse-Zuordnung bleiben erhalten.') ?></p><p><?= $financeHelpHtml('Eine tatsächlich zurückgezahlte Zahlung besteht aus zwei echten Geldbewegungen: Original und Rückzahlung benötigen jeweils ihren eigenen Banknachweis. Die zurückgezahlte Originalzahlung trägt einen eigenen Hinweis mit Belegzugang. Eine reine Ausgleichsbuchung für eine doppelte Übernahme ist keine Bankzahlung. Frühere Doppelübernahmen über <strong>Bisherige Entscheidung korrigieren</strong> auf die wirkliche vorhandene Zahlung zurückführen.') ?></p><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>
<section class="card" data-finance-help-topic id="gutschrift-rueckzahlung"><h2><?= $financeHelpHtml('Ausgestellte Gutschrift an den ursprünglichen Käufer zurückzahlen') ?></h2><p><?= $financeHelpHtml('Öffne die ausgestellte Gutschrift unter <strong>Ausgangsrechnungen → Gutschrift-Rückzahlung am tatsächlichen Beleg prüfen</strong>. Prüfe Gutschrift, Originalrechnung und tatsächlichen Zahlungseingang. Der Auftrag verwendet den noch offenen Gutschriftbetrag und die gespeicherte Bankverbindung des ursprünglichen Käufers. Ein freier Empfänger oder eine freie IBAN wird nicht angeboten. Bei einer 30-Euro-Gutschrift mit bereits zugeordneten 10 Euro werden nur 20 Euro vorbereitet.') ?></p><p><?= $financeHelpHtml('Vorbereitung, Freigabe und Bankdatei sind getrennte ausdrückliche Entscheidungen. Die Original-PDFs bleiben erhalten. Geänderte Bankdaten oder Zahlungen erfordern eine neue vollständige Prüfung. Ein Entwurf oder eine beliebige erzeugte Vorschau ist kein Gutschriftoriginal. Private Bankdaten und Zahlungsfreigaben benötigen ein bestätigtes Zahlungsamt oder den Superuser mit Finanz-Bearbeitungsrecht. Erst die tatsächliche zugeordnete Rückzahlung bezahlt die Gutschrift.') ?></p><p><?= $financeHelpHtml('Eine alte noch nicht exportierte Vorbereitung gegebenenfalls verwerfen und neu vom ursprünglichen Käufer ableiten. Bereits exportierte oder eingereichte Aufträge zuerst bei der Bank klären. Frühere Originale bleiben im Verlauf; dieselbe Bankdatei nicht erneut einreichen.') ?></p><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>
<section class="card" data-finance-help-topic id="ueberschuss-rueckzahlung"><h2><?= $financeHelpHtml('Zurückgezahlten Zahlungsüberschuss zuordnen') ?></h2><p><?= $financeHelpHtml('Beispiel: Ein 100-Euro-Beleg ist bezahlt, tatsächlich sind 105 Euro eingegangen und 5 Euro wurden zurückgezahlt. Öffne den ursprünglichen Umsatz und <strong>Überschussrückzahlung zuordnen → Vorhandene Rückzahlung auswählen</strong>. Suche die bereits erfasste Gegenbewegung auf demselben Konto, prüfe Betrag, Datum und Belegbezug und bestätige erst danach die Zuordnung. Die Forderung bleibt 100 Euro; eine weitere Zahlung wird nicht erfasst oder gesendet. Das gilt entsprechend für den Rückerhalt einer zu hohen eigenen Zahlung.') ?></p><p><?= $financeHelpHtml('Suche und Seitenwechsel erhalten deine Angaben. Teilrückzahlungen lassen den noch ungeklärten Rest sichtbar. Gebühren benötigen ihren eigenen Ausgabebeleg. Der Verlauf steht an beiden Umsätzen und am ursprünglich geprüften Beleg. Eine falsche Verknüpfung über <strong>Rückzahlungsbezug aufheben</strong> mit eigenem Grund lösen. Bei einer unterbrochenen Antwort dieselbe Kennung erneut prüfen. Finanzleser sehen die Originale ohne Änderungsformulare.') ?></p><p><?= $financeHelpHtml('Die Auswertungen behandeln den Rücklauf als Verrechnung. Für den vollständigen DATEV-Zahlungsstapel die abgestimmten Bestandskonten im Exportformular auswählen; im Belegpaket bleiben die ursprünglichen Nachweise erhalten.') ?></p><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>

<section class="card" data-finance-help-topic id="bank-abrufe"><h2><?= $financeHelpHtml('Bankabrufe vor der Belegzuordnung prüfen') ?></h2><ol>
<li><?= $financeHelpHtml('Unter <strong>Bank & Kasse → Bankabrufe prüfen</strong> das Konto und den Status auswählen. <strong>Zu prüfen</strong> zeigt ungeklärte oder von der Bank geänderte Zeilen. <strong>Alle Bankzeilen</strong> zeigt auch frühere Übernahmen, Vormerkungen und Entscheidungen. Suche, Zeitraum und weitere Seiten erreichen ältere Originale.') ?></li>
<li><?= $financeHelpHtml('Eine <strong>Bankzeile prüfen</strong>. Gespeicherten Bankstand und die <strong>von der Bank gelieferten Originale</strong> vergleichen. Frühere Abrufe und ihre Originaldateien bleiben im selben Vorgang lesbar.') ?></li>
<li><?= $financeHelpHtml('Ist die Zahlung schon erfasst, <strong>Mit einer vorhandenen Zahlung verbinden</strong> wählen, die tatsächliche Zahlung suchen und auswählen. <strong>Als zusätzliche tatsächliche Zahlung übernehmen</strong> benötigt die ausdrückliche Bestätigung, dass eine weitere bisher fehlende Zahlung erfolgt ist. <strong>Nicht zusätzlich buchen</strong> dokumentiert zum Beispiel eine schon im Anfangsbestand enthaltene Zahlung.') ?></li>
<li><?= $financeHelpHtml('Bei einer Bankänderung den gespeicherten Stand und die neu gelieferten Werte vergleichen. <strong>Gespeicherten Stand beibehalten</strong> bestätigt diese Prüfung und verändert keinen Kontostand. Eine erforderliche tatsächliche Buchhaltungskorrektur gesondert mit ihrem Nachweis bearbeiten.') ?></li>
<li><?= $financeHelpHtml('Den Grund angeben und <strong>Geprüfte Entscheidung speichern</strong> wählen. Bei einer Ablehnung bleiben Auswahl, Grund und ursprüngliche Prüffassung erhalten. <strong>Aktuellen Bankstand prüfen</strong> liest nur neu; anschließend gesondert speichern. Ein unbestätigter Ausgang wird zuerst im selben Vorgang und seinem Verlauf gelesen.') ?></li>
<li><?= $financeHelpHtml('Eine bereits angenommene Entscheidung unter <strong>Bisherige Entscheidung korrigieren</strong> mit Grund und Bestätigung korrigieren: eine Nichtbuchungsentscheidung wieder öffnen, einen falsch verbundenen Banknachweis lösen oder eine doppelte Übernahme auf die tatsächliche vorhandene Zahlung zurückführen. Nur die doppelte Übernahme benötigt ein Korrekturdatum und erzeugt eine Gegenbuchung. Vorherige Beleg- und Geldtransferzuordnungen zuerst begründet lösen; ausgestellte Spendenbescheinigungen schützen ihre Zahlungsnachweise.') ?></li>
<li><?= $financeHelpHtml('<strong>Bankkorrekturen</strong> zeigt den früheren Kontoumsatz, den tatsächlichen Kontoumsatz und gegebenenfalls die Gegenbuchung. <strong>Korrekturoriginal herunterladen</strong> enthält den ganzen vorherigen Stand mit Begründung. Auch hier liest <strong>Aktuellen Bankstand prüfen</strong> nur neu; erst <strong>Geprüfte Bankkorrektur speichern</strong> bestätigt die Änderung.') ?></li>
<li><?= $financeHelpHtml('Nach einer unterbrochenen Übernahme <strong>Gespeicherten Bankstand prüfen</strong> wählen. Die ursprüngliche Kontowahl und Übernahme bleiben im Fehlerformular erhalten. <strong>Ursprüngliche Übernahme erneut prüfen</strong> liest einen bereits gespeicherten Ausgang auch nach geschlossenem Bankdialog. Bei Erfolg öffnet sich die Übersicht der gespeicherten Bankzeilen. Einen als unbestätigt gemeldeten Abruf zuerst anhand dieses Bankstands prüfen; <strong>Aktuellen Bankabruf neu öffnen</strong> öffnet bei Bedarf ein neues Formular.') ?></li>
<li><?= $financeHelpHtml('<strong>Übernommenen Kontoumsatz öffnen</strong> führt zur Zuordnung des tatsächlichen Geldflusses zu einer Rechnung, einem Beitrag oder einem anderen passenden Beleg. <strong>Zur Bankübernahmeprüfung</strong> führt mit den bisherigen Filtern zurück.') ?></li>
</ol><p><?= $financeHelpHtml('Diese Prüfung verwendet gespeicherte Bankdaten und benötigt keinen neuen Bankdialog. Finanz-Bearbeitungsrecht ist erforderlich.') ?></p><?php if($finance->canWrite()): ?><p><a class="btn btn-outline theme-secondary" href="?view=finance&amp;tab=bank&amp;bank_import=1"><?= $financeHelpHtml('Gespeicherte Bankzeilen prüfen') ?></a></p><?php endif ?><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>

<section class="card" data-finance-help-topic id="bank-zuordnung"><h2><?= $financeHelpHtml('Bankumsätze und Vereinszahlungen zuordnen') ?></h2><ol>
<li><?= $financeHelpHtml('Unter <strong>Bank & Kasse</strong> das Konto auswählen. Suche, Buchungszeitraum, Zahlungsrichtung und Betrag grenzen alle passenden Umsätze ein. Auch ältere Umsätze sind über die Suche und weiteren Seiten erreichbar.') ?></li>
<li><?= $financeHelpHtml('<strong>Offen und teilweise</strong> zeigt noch zu prüfende Beträge. <strong>Umsätze dieser Seite prüfen</strong> ordnet nur die angezeigten Umsätze mit eindeutigem Belegbezug zu. Andere Umsätze bleiben zur eigenen Prüfung offen.') ?></li>
<li><?= $financeHelpHtml('Einen Umsatz öffnen und den tatsächlichen Beleg suchen, etwa eine Beitragsrechnung, Einnahme oder Ausgabe. Konto, Person, Verwendungszweck und offenen Betrag vergleichen. Für Teilzahlungen nur den tatsächlich zugehörigen Teilbetrag zuordnen.') ?></li>
<li><?= $financeHelpHtml('Alternativ vom Beleg aus <strong>Vorhandenen Kontoumsatz zuordnen</strong> öffnen. Eine bereits importierte oder erfasste Zahlung wird nicht noch einmal als neue Zahlung erfasst.') ?></li>
<li><?= $financeHelpHtml('Fehlt der passende Beleg, am Umsatz <strong>Neuen Beleg zu diesem Umsatz erfassen</strong> öffnen. Konto, Datum und Betrag stammen aus dem vorhandenen Umsatz. Nach dem Speichern bleibt dieser Umsatz vorgewählt. Bei Ausgaben zuerst das Original hinzufügen, prüfen und freigeben; danach den tatsächlichen Betrag zuordnen. <strong>Zum ursprünglichen Kontoumsatz</strong> führt mit den bisherigen Bankfiltern zurück.') ?></li>
<li><?= $financeHelpHtml('Eine falsche Belegverknüpfung unter <strong>Zuordnungen & Verlauf → Zuordnung aufheben</strong> mit einem Grund lösen. Bei einer Ablehnung bleibt der Grund erhalten. <strong>Aktuellen Stand prüfen</strong> liest die jetzige Zuordnung; das Aufheben danach gesondert bestätigen. Betrag und ursprünglicher Kontoumsatz bleiben erhalten. Im Verlauf stehen der ursprüngliche Grund und der Rückweg zum Beleg beziehungsweise Umsatz.') ?></li>
</ol><p><?= $financeHelpHtml('Eine Überweisung an Dritte beginnt an einer offenen Ausgabenrechnung oder freigegebenen Erstattung. Empfänger und Betrag bleiben an diesen Vorgang gebunden. Ein vorbereiteter oder eingereichter Auftrag bestätigt noch keine Zahlung; dafür wird anschließend der tatsächliche Kontoumsatz zugeordnet.') ?></p><p><a class="btn btn-outline theme-secondary" href="?view=finance&amp;tab=bank&amp;assignment=pending"><?= $financeHelpHtml('Noch zuzuordnende Umsätze öffnen') ?></a></p><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>

<section class="card" data-finance-help-topic id="rueckzahlung"><h2><?= $financeHelpHtml('Tatsächliche Rückzahlung zum Beleg zuordnen') ?></h2><ol>
<li><?= $financeHelpHtml('Den vollständig und ungeteilt bezahlten Beleg öffnen und <strong>Geldfluss durch Gegenbuchung korrigieren</strong> wählen. Eine ausgegebene Ausgangsrechnung wird über ihren eigenen Storno-/Gutschriftweg korrigiert.') ?></li>
<li><?= $financeHelpHtml('Zuerst über <strong>Alle passenden Kontoumsätze ansehen</strong> auch bereits anderweitig zugeordnete oder korrigierte Bewegungen vergleichen. Eine falsche Zuordnung dort am Umsatz mit Grund lösen. Danach unter <strong>Bereits erfasste Gegenbewegung auswählen</strong> nach der nun freien tatsächlichen Rückzahlung suchen. Weitere Seiten enthalten auch ältere passende Umsätze. Konto, Person, Betrag und Zahlungsnachweis vergleichen und <strong>Diese Gegenbewegung verwenden</strong> wählen. Das tatsächliche Datum wird übernommen; der Kontostand bleibt erhalten.') ?></li>
<li><?= $financeHelpHtml('Nur wenn die tatsächlich erfolgte Gegenbewegung noch nicht erfasst ist, das wirkliche Datum angeben und die ausdrückliche Bestätigung zur zusätzlichen Bewegung setzen. Dieser Weg ergänzt einen entgegengesetzten Kontoumsatz und verändert den Kontostand.') ?></li>
<li><?= $financeHelpHtml('Einen nachvollziehbaren <strong>Grund</strong> mit höchstens 500 Zeichen angeben und <strong>Geprüfte Gegenbuchung speichern</strong>. Bei einer zwischenzeitlichen Änderung bleiben Eingaben und Auswahl erhalten. <strong>Aktuellen Korrekturstand prüfen</strong> liest die aktuelle Fassung und passenden Gegenbewegungen. Bei neuen Treffern wird die frühere Bestätigung zur zusätzlichen Bewegung zurückgesetzt. Vorhandene Zahlungen erneut vergleichen und anschließend gesondert speichern.') ?></li>
<li><?= $financeHelpHtml('Trifft der Banknachweis erst später ein, unter <strong>Bankabrufe prüfen</strong> die bereits erfasste Gegenbewegung als <strong>Vorhandene Zahlung</strong> auswählen. Sie wird nicht noch einmal als neue Zahlung gebucht. Der ursprüngliche Beleg und beide Bewegungen bleiben nachvollziehbar.') ?></li>
</ol><p><?= $financeHelpHtml('Diese Zuordnung überweist kein Geld. Eine bloß falsche Belegverknüpfung wird über <strong>Zuordnung aufheben</strong> korrigiert. Zuwendungsbescheinigungen und abgeschlossene Kassenzeiträume behalten ihren Schutz. Eine Rücklastschrift zu einer weiter offenen Beitragsforderung wird im vorhandenen Lastschriftauftrag dokumentiert.') ?></p><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>

<section class="card" data-finance-help-topic id="eigene-geldtransfers"><h2><?= $financeHelpHtml('Abhebung, Einzahlung und eigener Kontoübertrag') ?></h2><ol>
<li><?= $financeHelpHtml('Den vorhandenen Bankumsatz öffnen und <strong>Vorhandenen Gegenumsatz auf eigenem Konto zuordnen</strong> wählen. Den tatsächlichen Zugang beziehungsweise Abgang auf einem anderen eigenen Konto suchen, Betrag und Nachweis vergleichen und bewusst zuordnen.') ?></li>
<li><?= $financeHelpHtml('Fehlt der Kassenumsatz noch, die passende <strong>tatsächliche Bargeldbewegung erfassen</strong>. Handkasse, wirklichen Tag, Betrag und Grund angeben und ausdrücklich bestätigen, dass die Bewegung erfolgt und noch nicht erfasst ist.') ?></li>
<li><?= $financeHelpHtml('Gebühren getrennt behandeln: Bei 100 Euro Bargeld und 3 Euro Bankgebühr werden 100 Euro als eigener Geldtransfer und 3 Euro einem Ausgabebeleg zugeordnet.') ?></li>
<li><?= $financeHelpHtml('Eine falsche Transferzuordnung im Verlauf mit Korrekturgrund aufheben. Beide ursprünglichen Umsätze bleiben bestehen. Ein Kassenabschluss schützt vergangene Buchungen und Zuordnungen.') ?></li>
</ol><p><?= $financeHelpHtml('Geld zwischen eigenen Konten zählt nicht als Einnahme oder Ausgabe. Diese Zuordnung löst keine Überweisung aus. Sie verbindet tatsächlich erfolgte Bewegungen.') ?></p><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>

<section class="card" data-finance-help-topic id="restbeitrag"><h2><?= $financeHelpHtml('Nur den offenen Restbeitrag einziehen') ?></h2><p><?= $financeHelpHtml('Eine ursprüngliche 100-Euro-Beitragsrechnung mit 60 Euro zugeordneter Zahlung kann über die offenen 40 Euro vorangekündigt und als eigener Lastschriftauftrag vorbereitet werden. Rechnungsauswahl und Prüfung unterscheiden ursprünglichen Betrag, bereits bezahlt und noch einzuziehen. Ein freier Einzugsbetrag wird nicht eingegeben.') ?></p><p><?= $financeHelpHtml('Freigabe und Bankdateiexport brauchen jeweils eine eigene Prüfung und Zustimmung. Erst tatsächliche Geldbewegungen verändern den Zahlungsstand. Bei einer Rücklastschrift dieses 40-Euro-Postens wählen Sie seinen wirklichen Rückumsatz und genau die ursprüngliche 40-Euro-Zahlungszuordnung: 60 Euro bleiben bezahlt, 40 Euro werden offen. Die Originalrechnung und frühere Bankdateien bleiben erhalten.') ?></p><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>

<section class="card" data-finance-help-topic id="sonderfaelle"><h2><?= $financeHelpHtml('Sonderfälle') ?></h2><ul>
<li><?= $financeHelpHtml('<strong>Mitglied hat privat bezahlt:</strong> Mitglied beim Rechnungseingang auswählen. Die Rechnung wird als Erstattung geführt.') ?></li>
<li><?= $financeHelpHtml('<strong>Inventar:</strong> Rechnung prüfen, danach die einzelnen Positionen dem Inventar zuordnen.') ?></li>
<li><?= $financeHelpHtml('<strong>Unklare Zuordnung:</strong> Rechnung speichern und später mit dem Original klären.') ?></li>
</ul><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>

<section class="card" data-finance-help-topic id="export"><h2><?= $financeHelpHtml('Export') ?></h2><p><?= $financeHelpHtml('Nach der Prüfung öffnen Sie den Export, wählen den Zeitraum und laden die Belegliste oder das Belegpaket herunter.') ?></p><p><a class="btn btn-outline theme-secondary button secondary" href="?view=finance&amp;tab=export"><?= $financeHelpHtml('Export öffnen') ?></a></p><p class="finance-help-return"><a href="#finanzthemen"><?=e($financeHelpText('Zur Themenübersicht'))?></a></p></section>
</div>
